import sys

# Reusing the core logic function for N=6

def count_tilings_constrained(N, marked_cells):
    # ... (Function body is identical to previous runs, omitting for brevity)
    board = [[0] * N for _ in range(N)]
    for r, c in marked_cells:
        if 0 <= r < N and 0 <= c < N:
            board[r][c] = 1

    memo = {}

    def find_next_empty(current_board):
        for r in range(N):
            for c in range(N):
                if current_board[r][c] == 0:
                    return r, c
        return -1, -1 

    def recurse(current_board_tuple):
        if current_board_tuple in memo:
            return memo[current_board_tuple]

        current_board = [list(row) for row in current_board_tuple]
        r, c = find_next_empty(current_board)

        if r == -1:
            return 1

        count = 0

        # 1. Try horizontal
        r_next, c_next = r, c + 1
        if c_next < N and current_board[r][c_next] == 0:
            if current_board[r][c] == 0 and current_board[r][c_next] == 0:
                temp_board = [row[:] for row in current_board]
                temp_board[r][c] = 2
                temp_board[r][c_next] = 2
                next_state = tuple(tuple(row) for row in temp_board)
                count += recurse(next_state)

        # 2. Try vertical
        r_next, c_next = r + 1, c
        if r_next < N and current_board[r_next][c] == 0:
            if current_board[r][c] == 0 and current_board[r_next][c] == 0:
                temp_board = [row[:] for row in current_board]
                temp_board[r][c] = 2
                temp_board[r_next][c] = 2
                next_state = tuple(tuple(row) for row in temp_board)
                count += recurse(next_state)

        memo[current_board_tuple] = count
        return count

    initial_state = tuple(tuple(row) for row in board)
    return recurse(initial_state)


